const data = $input.first().json;
const t = data.edtTemplate || {};

function esc(v){
  return String(v ?? '')
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#39;');
}

const colonnes = Array.isArray(t.colonnes) && t.colonnes.length === 6
  ? t.colonnes
  : ['Heures','Lundi','Mardi','Mercredi','Jeudi','Vendredi'];
const lignes = Array.isArray(t.lignes) ? t.lignes : [];
const separateurs = new Set(Array.isArray(t.separateurs) ? t.separateurs : [2]);

function renderCell(cell){
  if (!cell || cell.type === 'skip') return '';
  const rowSpan = Math.max(1, Number(cell.rowSpan || 1));
  if (cell.type === 'empty') {
    return `<td rowspan="${rowSpan}" style="border:1px solid #000;min-height:68px;height:68px;"></td>`;
  }
  const module = esc(cell.module || cell.matiere || '');
  const salle = esc(cell.salle || '');
  const professeur = esc(cell.professeur || '');
  return `<td rowspan="${rowSpan}" style="border:1px solid #000;padding:6px;vertical-align:top;min-height:68px;">
    <span style="background:#FFF59D;font-weight:700;font-size:11px;display:block;padding:2px 4px;">${module}</span>
    <span style="background:#FFF59D;font-size:11px;display:block;padding:2px 4px;">${salle ? 'Salle ' + salle : ''}</span>
    <span style="font-size:11px;display:block;margin-top:2px;">${professeur}</span>
  </td>`;
}

const thead = `<tr>${colonnes.map((c, i) => `<th style="border:1px solid #000;padding:5px;font-size:11px;text-align:${i===0?'center':'left'};${i===0?'width:65px;':''}">${esc(c)}</th>`).join('')}</tr>`;

const bodyRows = [];
for (let i = 0; i < lignes.length; i++) {
  if (separateurs.has(i)) {
    bodyRows.push('<tr><td colspan="6" style="background:#4472C4;height:14px;border:none;"></td></tr>');
  }
  const ligne = lignes[i] || {};
  const cells = Array.isArray(ligne.cells) ? ligne.cells : [];
  bodyRows.push(`<tr><td style="border:1px solid #000;color:#C00000;font-weight:700;font-size:11px;text-align:center;vertical-align:middle;">${esc(ligne.heureLabel || '')}</td>${cells.map(renderCell).join('')}</tr>`);
}

const introBanner = data.introIA
  ? `<div style="background:#F0F9FF;border-left:4px solid #0EA5E9;padding:12px 16px;margin-bottom:16px;border-radius:0 6px 6px 0;"><p style="color:#0C4A6E;font-size:13px;margin:0;line-height:1.5;font-style:italic;">${esc(data.introIA)}</p><p style="color:#0EA5E9;font-size:10px;margin:6px 0 0;">— Message personnalise genere par Gemini 3 Flash</p></div>`
  : '';

const iaBanner = data.iaActive && data.suggestions
  ? `<div style="background:#EEF2FF;border-left:4px solid #4338CA;padding:10px 14px;margin-bottom:16px;border-radius:0 6px 6px 0;"><strong style="color:#4338CA;font-size:12px;">Optimise par Gemini 3 Flash</strong><p style="color:#374151;font-size:11px;margin:4px 0 0;">${esc(data.suggestions)}</p></div>`
  : '';

const html = `<!DOCTYPE html><html><head><meta charset='utf-8'><style>body{font-family:Arial,sans-serif;padding:28px;background:#fff;color:#000;}table{border-collapse:collapse;width:100%;}</style></head><body>
<div style="margin-bottom:20px;"><img src="https://frontend-angular-planning.vercel.app/isd-logo.svg" alt="Institut Superieur du Digital" style="height:64px;width:auto;display:block;"></div>
${introBanner}
${iaBanner}
<div style="text-align:center;font-weight:bold;font-size:15px;text-decoration:underline;text-transform:uppercase;margin-bottom:5px;">${esc(t.titre || '')}</div>
<div style="text-align:center;font-size:13px;text-decoration:underline;text-transform:uppercase;margin-bottom:18px;">${esc(t.sousTitre || '')}</div>
<table><thead>${thead}</thead><tbody>${bodyRows.join('')}</tbody></table>
<p style="color:#C00000;font-style:italic;font-weight:bold;text-decoration:underline;margin-top:18px;font-size:12px;">${esc(t.noteBasPage || "NB : L'emploi du temps n'est pas definitif. Il peut toujours subir des modifications.")}</p>
</body></html>`;

return [{ json: { ...data, htmlEmail: html } }];
